fn longest_palindromic_substring(s: &str) -> String {
    // Support function to convert an input string into a modified version
    // that will have non-palindromic segments separated by delimiter characters `#`.
    // This helps handle even-length and odd-length palindromes uniformly.
    fn preprocess(s: &str) -> String {
        if s.is_empty() {
            return "#".to_string();
        }
        let mut chars: Vec<char> = s.chars().collect();
        chars.insert(0, '^');
