    let modified = preprocess(s);
    let n = modified.len();
    let mut p = vec![0; n]; // Array to store the radius of the palindrome centered at each position
    let mut center = 0; // Center of the largest palindrome found so far
    let mut right = 0; // Right edge of the largest palindrome found so far
    let mut max_len = 0; // Length of the longest palindrome found
    let mut max_center = 0; // Center position of the longest palindrome found

    for i in 1..(n - 1) {
        if i < right {
            p[i] = p[2 * center - i].min(right - i);
        }

        // Attempt to expand around the center
        while modified[i + 1 + p[i]] == modified[i - 1 - p[i]] {
            p[i] += 1;
        }

        // Update the center and right edge of the largest palindrome found
